-- FoodLife drinks import generated from databaze/podklady/all_drinks_nutrition_database_cz.csv
-- Values from the source are per 100 ml. FoodLife stores them in *_100g columns and treats 1 ml ~= 1 g for logging.
-- Safe to import repeatedly thanks to uniq_food_external (external_source, external_code).

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
  `name_cs` = VALUES(`name_cs`),
  `name_en` = VALUES(`name_en`),
  `category` = VALUES(`category`),
  `default_unit` = VALUES(`default_unit`),
  `serving_grams` = VALUES(`serving_grams`),
  `energy_kj_100g` = VALUES(`energy_kj_100g`),
  `kcal_100g` = VALUES(`kcal_100g`),
  `protein_100g` = VALUES(`protein_100g`),
  `total_carbs_100g` = VALUES(`total_carbs_100g`),
  `carbs_100g` = VALUES(`carbs_100g`),
  `fat_100g` = VALUES(`fat_100g`),
  `sugar_100g` = VALUES(`sugar_100g`),
  `sodium_mg_100g` = VALUES(`sodium_mg_100g`),
  `salt_100g` = VALUES(`salt_100g`),
  `note` = VALUES(`note`);

ON DUPLICATE KEY UPDATE
  `name_cs` = VALUES(`name_cs`),
  `name_en` = VALUES(`name_en`),
  `category` = VALUES(`category`),
  `default_unit` = VALUES(`default_unit`),
  `serving_grams` = VALUES(`serving_grams`),
  `energy_kj_100g` = VALUES(`energy_kj_100g`),
  `kcal_100g` = VALUES(`kcal_100g`),
  `protein_100g` = VALUES(`protein_100g`),
  `total_carbs_100g` = VALUES(`total_carbs_100g`),
  `carbs_100g` = VALUES(`carbs_100g`),
  `fat_100g` = VALUES(`fat_100g`),
  `sugar_100g` = VALUES(`sugar_100g`),
  `sodium_mg_100g` = VALUES(`sodium_mg_100g`),
  `salt_100g` = VALUES(`salt_100g`),
  `note` = VALUES(`note`);
